// energy/degradation sketch for: Resource-Constrained Factory Simulator
let c = 1.0; const samples = [];
for (let i = 0; i < 503; i++) { c *= 0.99962; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 503, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

